ROOT=Path(__file__).resolve().parents[1]
with tempfile.TemporaryDirectory(prefix='cfs-compact-rows-') as tmp:
 fixture=Path(tmp)/'data.json';seed=json.loads(subprocess.check_output(['node','-e','process.stdout.write(JSON.stringify(require("./scripts/fixture").seed()))'],cwd=ROOT));first=next(iter(seed['remote']));generic_id=list(seed['remote'])[4];seed['remote'][first]['comments']='General delivery context.\n\n'+seed['remote'][first]['comments'];seed['docs']['epic:'+first]['comments']=seed['remote'][first]['comments'];seed['remote'][generic_id]['comments']='Design completed; validation continues.\n\n'+seed['remote'][generic_id]['comments'];seed['docs']['epic:'+generic_id]['comments']=seed['remote'][generic_id]['comments'];fixture.write_text(json.dumps(seed));server=subprocess.Popen(['node','server.js','--fixture'],cwd=ROOT,env={**os.environ,'PORT':'8408','CFS_FIXTURE_FILE':str(fixture)},stdout=subprocess.PIPE,text=True)
