   page.locator('#table-head [data-key="health"]').click();expect(page.locator('.epic-summary-row')).to_have_count(6);page.locator('#full-updates').click();expect(page.locator('.epic-detail-row')).to_have_count(6);page.locator('#full-updates').click();expect(page.locator('.epic-detail-row')).to_have_count(0)
